<?php
namespace Modules\Ran\Http\Controllers;use Modules\Ran\Entities\{Sale,StockLot};use Modules\Ran\Http\Requests\SaleRequest;use Modules\Ran\Integrations\CustomerIntegrationService;use Modules\Ran\Services\SaleService;
class SaleController extends RanController{public function __construct(private SaleService $service,private CustomerIntegrationService $customers){}public function index(){return view('ran::sales.index',['sales'=>Sale::query()->with('customer')->latest('invoice_date')->latest('id')->paginate(25)]);}public function create(){return view('ran::sales.form',array_merge($this->pageOptions(),['customers'=>$this->customers->dropdown(),'lots'=>StockLot::query()->with('item')->where('stock_status','available')->where(function($q){$q->where('quantity','>',0)->orWhere('net_weight','>',0);})->orderBy('lot_no')->get()]));}public function store(SaleRequest $r){$s=$this->service->create($r->validated());return $this->success('Sale saved as draft.','ran.sales.show',[$s]);}public function show(Sale $sale){return view('ran::sales.show',['sale'=>$sale->load('lines.item','lines.stockLot','payments','returns')]);}public function post(Sale $sale){$this->service->post($sale);return back()->with('status','Sale posted to stock, customer ledger and Finance.');}}
